<script setup lang="ts">
import { ref, reactive, computed, watch, onMounted } from 'vue'
import { message } from 'ant-design-vue'
import { SearchOutlined, PlusOutlined } from '@ant-design/icons-vue'
import { listPeople, getEmployeeMetadata, createEmployee } from '@/services/iamPeople'
import { canIam, iamMessage } from '@/services/iamAccess'
import type { EmployeeSummary, EmployeeMetadata } from '@/types/iam'
import EmployeeDrawer from '@/components/iam/EmployeeDrawer.vue'
import OwnAccountVerification from '@/components/account/OwnAccountVerification.vue'
import { useAccountProof } from '@/composables/useAccountProof'
const rows = ref<EmployeeSummary[]>([]), total = ref(0), page = ref(1), category = ref('employees'), search = ref(''), department = ref(''), accountStatus = ref(''), loading = ref(true), error = ref('')
const selected = ref(''), selectedTab = ref('basic'), drawerOpen = ref(false), createOpen = ref(false), metadata = ref<EmployeeMetadata | null>(null), creating = ref(false), createError = ref('')
const fields = reactive<Record<string,string>>({}), proof = useAccountProof(() => undefined)
let generation = 0, timer: ReturnType<typeof setTimeout> | undefined, requestId = ''
const columns = computed(() => category.value === 'employees' ? [{title:'姓名 / 工号',key:'name',width:'25%'},{title:'部门 / 岗位',key:'department',width:'27%'},{title:'账号状态',key:'account',width:'17%'},{title:'考勤关联',key:'attendance',width:'15%'},{title:'操作',key:'action',width:'16%'}] : [{title:'账号名称',key:'name',width:'35%'},{title:'账号主键',dataIndex:'user_id',width:'40%'},{title:'分类',key:'category',width:'25%'}])
const formFields = computed(() => metadata.value?.required_fields.filter(row => !['name','user_id','create_user_automatically','status'].includes(row.fieldname)) || [])
async function load() { const run = ++generation; loading.value = true; error.value = ''; try { const result = await listPeople({page:page.value,page_size:20,category:category.value,search:search.value,department:department.value,account_status:accountStatus.value}); if (run === generation) { rows.value = result.items; total.value = result.total } } catch(e) { if (run === generation) { rows.value=[]; total.value=0; error.value=iamMessage(e) } } finally { if(run===generation)loading.value=false } }
function open(row: EmployeeSummary, tab='basic') { selected.value=row.id; selectedTab.value=tab; drawerOpen.value=true }
async function beginCreate() { createError.value=''; proof.invalidate(); Object.keys(fields).forEach(key=>delete fields[key]); requestId=crypto.randomUUID(); try { metadata.value=await getEmployeeMetadata(); createOpen.value=true } catch(e) { error.value=iamMessage(e) } }
function options(field: string) { return field === 'company' ? metadata.value?.companies : field === 'department' ? metadata.value?.departments.filter(row=>!fields.company || row.company===fields.company) : field === 'gender' ? metadata.value?.genders : undefined }
async function saveEmployee() { if(creating.value || !metadata.value || !proof.valid.value)return; const missing=formFields.value.filter(row=>!fields[row.fieldname]?.trim()).map(row=>row.label); if(missing.length){createError.value=`请填写：${missing.join('、')}。`;return}; creating.value=true;createError.value='';try { await createEmployee({...fields,status:'Active'},metadata.value.version,requestId); createOpen.value=false;proof.invalidate();message.success('员工档案已保存，尚未开通账号。');await load() } catch(e){createError.value=iamMessage(e)}finally{creating.value=false} }
watch([category,department,accountStatus],()=>{page.value=1;void load()});watch(search,()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,300)});watch(()=>fields.company,()=>{fields.department=''});onMounted(load)
</script>
<template><section><div class="iam-heading"><div><h1>员工管理</h1><p>查看员工资料、开通账号与应用安排。</p></div><a-button v-if="canIam('iam.people.create')" type="primary" @click="beginCreate"><PlusOutlined />新增员工</a-button></div><section class="iam-panel"><a-tabs v-model:activeKey="category"><a-tab-pane key="employees" tab="员工"/><a-tab-pane key="pending" tab="待关联账号"/><a-tab-pane key="other" tab="其他账号"/></a-tabs><p v-if="category !== 'employees'" class="aux">{{category==='pending'?'这些账号尚未明确关联Employee，不能查看本人考勤；请核验后关联已有员工。':'服务与应急管理账号独立列示，不计入员工档案。'}}</p><div class="iam-toolbar"><a-input v-model:value="search" allow-clear class="iam-search" :placeholder="category==='employees'?'搜索姓名、工号或登录名':'搜索账号'" aria-label="搜索人员"><template #prefix><SearchOutlined /></template></a-input><a-select v-if="category==='employees'" v-model:value="accountStatus" aria-label="账号状态" style="min-width:160px"><a-select-option value="">全部账号状态</a-select-option><a-select-option value="active">已开通</a-select-option><a-select-option value="unopened">未开通</a-select-option><a-select-option value="disabled">已停用</a-select-option></a-select></div><a-alert v-if="error" :message="error" type="warning" show-icon/><a-table :columns="columns" :data-source="rows" row-key="id" table-layout="fixed" :loading="loading" :scroll="{x:700}" :pagination="{current:page,pageSize:20,total,showSizeChanger:false,onChange:(value:number)=>{page=value;load()}}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><button v-if="category==='employees'" class="iam-name" :aria-label="`查看${record.name}，工号${record.employee_number}`" @click="open(record)"><strong>{{record.name}}</strong></button><strong v-else>{{record.name}}</strong><span class="iam-code">{{record.employee_number || record.id}}</span></template><template v-else-if="column.key==='department'"><span>{{record.department_name}}</span><span class="iam-code">{{record.position || '岗位待补充'}}</span></template><template v-else-if="column.key==='account'"><a-tag>{{record.account_status==='active'?'已开通':record.account_status==='disabled'?'已停用':'未开通'}}</a-tag></template><template v-else-if="column.key==='attendance'"><a-tag :color="record.attendance_status==='confirmed'?'green':'gold'">{{record.attendance_status==='confirmed'?'已确认':'待确认'}}</a-tag></template><template v-else-if="column.key==='action'"><a-button type="link" @click="open(record,record.user_id?'basic':'account')">{{record.user_id?'查看':'开户 / 关联'}}</a-button></template><template v-else-if="column.key==='category'">{{category==='pending'?'员工待关联':'非员工主体'}}</template></template></a-table><p class="aux">考勤关联显示身份核验状态；没有打卡记录不代表尚未关联。</p><a-button v-if="error" @click="load">重试读取</a-button></section><EmployeeDrawer :open="drawerOpen" :employee-id="selected" :initial-tab="selectedTab" @close="drawerOpen=false" @changed="load"/>
<a-modal v-model:open="createOpen" title="新增员工档案" :footer="null" :mask-closable="false"><p>此步骤只建立原生员工档案。公司和部门从获准的现有组织中选择，不自动开户。</p><a-alert v-if="createError" :message="createError" type="warning"/><OwnAccountVerification password-only @verified="proof.sync" @invalidated="proof.invalidate"/><a-form layout="vertical" @submit.prevent="saveEmployee"><a-form-item v-for="field in formFields" :key="field.fieldname" :label="field.label" required><a-select v-if="options(field.fieldname)" v-model:value="fields[field.fieldname]" :options="options(field.fieldname)"/><a-input v-else v-model:value="fields[field.fieldname]" :type="field.fieldtype==='Date'?'date':'text'" autocomplete="off"/></a-form-item><a-button :disabled="creating" @click="createOpen=false;proof.invalidate()">取消</a-button><a-button type="primary" html-type="submit" :loading="creating" :disabled="!proof.valid.value">保存员工档案</a-button></a-form></a-modal></section></template>
